import numpy as np
d = np.load('source_pixels.npz')
a = d['rgb'].astype(int)

def classify(px):
    r,g,b = px
    # background grayish
    if abs(r-g)<14 and abs(g-b)<18 and r>140:
        return '.'  # light gray bg
    if r>100 and g<100 and b<90 and r>g+25:
        return 'B'  # brown (wood)
    if r<90 and g<80 and b<70:
        return '#'  # dark
    if g>r and g>b:
        return 'G'
    if b>r and b>g:
        return 'U'
    return 'o'

for fi in [0, 24, 48, 72, 95]:
    f = a[fi]
    print('=== frame', fi)
    H,W,_ = f.shape
    small = f[::4,::3]
    for row in small:
        print(''.join(classify(px) for px in row))
